#include <cppconn/prepared_statement.h>

void addStudent(sql::Connection* con, int roll, const string& name,
                const string& cls, char gender, int marks, const string&
city) {
    unique_ptr<sql::PreparedStatement> ps(con->prepareStatement(
        "INSERT INTO STUDENT (RollNo, Name, Class, Gender, Marks, City) "
        "VALUES (?, ?, ?, ?, ?, ?)"));
    ps->setInt(1, roll);
    ps->setString(2, name);
    ps->setString(3, cls);
    ps->setString(4, string(1, gender));
    ps->setInt(5, marks);
    ps->setString(6, city);
    int rows = ps->executeUpdate();              // number of rows affected
    cout << rows << " record inserted" << endl;
}

