#include <iostream>
#include <memory>
#include <string>
#include <mysql_driver.h>
#include <mysql_connection.h>
#include <cppconn/prepared_statement.h>
#include <cppconn/resultset.h>
#include <cppconn/exception.h>
using namespace std;

void showAll(sql::Connection* con) {
    unique_ptr<sql::PreparedStatement> ps(con->prepareStatement(
        "SELECT RollNo, Name, Class, Marks FROM STUDENT ORDER BY RollNo"));
    unique_ptr<sql::ResultSet> r(ps->executeQuery());
    while (r->next())
        cout << r->getInt(1) << "  " << r->getString(2) << "  "
             << r->getString(3) << "  "
             << (r->isNull(4) ? string("NULL") : to_string(r->getInt(4))) <<
endl;
}

void search(sql::Connection* con, int roll) {
    unique_ptr<sql::PreparedStatement> ps(con->prepareStatement(
        "SELECT Name, Marks FROM STUDENT WHERE RollNo = ?"));
    ps->setInt(1, roll);
    unique_ptr<sql::ResultSet> r(ps->executeQuery());
    if (r->next()) cout << r->getString("Name") << " scored " << r-
>getInt("Marks") << endl;
    else           cout << "No student with roll " << roll << endl;
}

void updateMarks(sql::Connection* con, int roll, int marks) {
    unique_ptr<sql::PreparedStatement> ps(con->prepareStatement(
        "UPDATE STUDENT SET Marks = ? WHERE RollNo = ?"));
    ps->setInt(1, marks);
    ps->setInt(2, roll);
    cout << ps->executeUpdate() << " record(s) updated" << endl;
}

void removeStudent(sql::Connection* con, int roll) {
    unique_ptr<sql::PreparedStatement> ps(con->prepareStatement(
        "DELETE FROM STUDENT WHERE RollNo = ?"));
    ps->setInt(1, roll);
    cout << ps->executeUpdate() << " record(s) deleted" << endl;
}

